            "<span style=\"color:#F97583\">import</span><span style=\"color:#E1E4E8\"> { StripeTerminal, TerminalEventsEnum } </span><span style=\"color:#F97583\">from</span><span style=\"color:#9ECBFF\"> '@capacitor-community/stripe-terminal'</span><span style=\"color:#E1E4E8\">;</span>",
