            "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">addListener</span><span style=\"color:#E1E4E8\">(</span>",
            "<span style=\"color:#E1E4E8\">  TerminalEventsEnum.RequestedConnectionToken,</span>",
            "<span style=\"color:#F97583\">  async</span><span style=\"color:#E1E4E8\"> () </span><span style=\"color:#F97583\">=&gt;</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">    try</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> response</span><span style=\"color:#F97583\"> =</span><span style=\"color:#F97583\"> await</span><span style=\"color:#B392F0\"> fetch</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'https://example.com/connection/token'</span><span style=\"color:#E1E4E8\">, {</span>",
            "<span style=\"color:#E1E4E8\">        method: </span><span style=\"color:#9ECBFF\">'POST'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">        headers: {</span>",
            "<span style=\"color:#E1E4E8\">          Authorization: </span><span style=\"color:#9ECBFF\">`Bearer ${</span><span style=\"color:#E1E4E8\">accessToken</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#9ECBFF\">          'Content-Type'</span><span style=\"color:#E1E4E8\">: </span><span style=\"color:#9ECBFF\">'application/json'</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">        },</span>",
            "<span style=\"color:#E1E4E8\">      });</span>",
            "<span style=\"color:#F97583\">      if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">!</span><span style=\"color:#E1E4E8\">response.ok) </span><span style=\"color:#F97583\">throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">`Connection token request failed: ${</span><span style=\"color:#E1E4E8\">response</span><span style=\"color:#9ECBFF\">.</span><span style=\"color:#E1E4E8\">status</span><span style=\"color:#9ECBFF\">}`</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#F97583\">      const</span><span style=\"color:#79B8FF\"> data</span><span style=\"color:#F97583\"> =</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> response.</span><span style=\"color:#B392F0\">json</span><span style=\"color:#E1E4E8\">()) </span><span style=\"color:#F97583\">as</span><span style=\"color:#E1E4E8\"> { </span><span style=\"color:#FFAB70\">secret</span><span style=\"color:#F97583\">?:</span><span style=\"color:#79B8FF\"> unknown</span><span style=\"color:#E1E4E8\"> };</span>",
            "<span style=\"color:#F97583\">      if</span><span style=\"color:#E1E4E8\"> (</span><span style=\"color:#F97583\">typeof</span><span style=\"color:#E1E4E8\"> data.secret </span><span style=\"color:#F97583\">!==</span><span style=\"color:#9ECBFF\"> 'string'</span><span style=\"color:#F97583\"> ||</span><span style=\"color:#F97583\"> !</span><span style=\"color:#E1E4E8\">data.secret) {</span>",
            "<span style=\"color:#F97583\">        throw</span><span style=\"color:#F97583\"> new</span><span style=\"color:#B392F0\"> Error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Connection token response is missing secret'</span><span style=\"color:#E1E4E8\">);</span>",
            "<span style=\"color:#E1E4E8\">      }</span>",
            "<span style=\"color:#F97583\">      await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">setConnectionToken</span><span style=\"color:#E1E4E8\">({ token: data.secret });</span>",
            "<span style=\"color:#E1E4E8\">    } </span><span style=\"color:#F97583\">catch</span><span style=\"color:#E1E4E8\"> (error) {</span>",
            "<span style=\"color:#a0aab5\">      // An empty token fails the pending native callback instead of leaving it hanging.</span>",
            "<span style=\"color:#F97583\">      try</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#F97583\">        await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">setConnectionToken</span><span style=\"color:#E1E4E8\">({ token: </span><span style=\"color:#9ECBFF\">''</span><span style=\"color:#E1E4E8\"> });</span>",
            "<span style=\"color:#E1E4E8\">      } </span><span style=\"color:#F97583\">finally</span><span style=\"color:#E1E4E8\"> {</span>",
            "<span style=\"color:#E1E4E8\">        console.</span><span style=\"color:#B392F0\">error</span><span style=\"color:#E1E4E8\">(</span><span style=\"color:#9ECBFF\">'Unable to supply a connection token'</span><span style=\"color:#E1E4E8\">, error);</span>",
            "<span style=\"color:#E1E4E8\">      }</span>",
            "<span style=\"color:#E1E4E8\">    }</span>",
            "<span style=\"color:#E1E4E8\">  },</span>",
            "<span style=\"color:#E1E4E8\">);</span>",
            "",
            "<span style=\"color:#F97583\">await</span><span style=\"color:#E1E4E8\"> StripeTerminal.</span><span style=\"color:#B392F0\">initialize</span><span style=\"color:#E1E4E8\">({</span>",
            "<span style=\"color:#E1E4E8\">  isTest: </span><span style=\"color:#79B8FF\">true</span><span style=\"color:#E1E4E8\">,</span>",
            "<span style=\"color:#E1E4E8\">});</span>",
